using Xunit;
using HakutaiKagami.Core.Contracts;
namespace HakutaiKagami.Tests;
public sealed class HistoricalStartCatalogTests
{
    static SetupScenario Scenario()=>NewGameWorld.Scenario(HistoricalStartCatalog.Current);
    static ContractWorld New(string selected="person:yoshishige")=>NewGameWorld.Create(Scenario(),[],selected,20261022,NewGameWorld.CompactPersonalAuthority,HistoricalStartCatalog.Current);
    [Fact] public void PreUpgradeActualProfileRebuildsExactInitialHashWithoutMigration(){var bytes=File.ReadAllBytes(Path.Combine(AppContext.BaseDirectory,"Fixtures","pre-catalog-start-v1.json"));Assert.DoesNotContain("HistoricalCatalog",System.Text.Encoding.UTF8.GetString(bytes));var profile=ContractJson.Read<NewCampaignProfile>(bytes);Assert.Null(profile.HistoricalCatalog);Assert.Equal("29a0594ab45c0f14e9ed9ec472929618e0a191f0f4ec8277a4f4edcd4f0fec73",ContractJson.CanonicalHash(NewCampaignStore.Build(profile)));Assert.Equal(3,profile.Setup.People.Length);}
    [Fact] public void LegacyScenarioRemainsThreeAndEditionIsFive(){Assert.Equal(3,NewGameWorld.Scenario().People.Length);var s=Scenario();Assert.Equal(5,s.People.Length);Assert.Equal(5,s.Factions.Length);Assert.Equal("大友義鎮",s.People.Single(p=>p.Id=="person:yoshishige").Name);Assert.Equal("site:funai",s.People.Single(p=>p.Id=="person:yoshishige").Site);Assert.Equal("site:uchijo",s.People.Single(p=>p.Id=="person:takahisa").Site);Assert.Equal(108,s.Castles.Length);NewGameSetup.Validate(s);}
    [Theory][InlineData("")][InlineData("unknown")][InlineData("historical-start-west-v3")] public void UnknownEditionNeverFallsBack(string id){Assert.Throws<InvalidDataException>(()=>NewGameWorld.Scenario(id));Assert.Throws<InvalidDataException>(()=>NewGameWorld.Create(Scenario(),[],"person:yoshishige",historicalCatalog:id));}
    [Fact] public void MarkerAndRosterCannotBeMixed(){Assert.Throws<InvalidDataException>(()=>NewGameWorld.Create(Scenario(),[],"person:yoshishige"));Assert.Throws<InvalidDataException>(()=>NewGameWorld.Create(NewGameWorld.Scenario(),[],"person:nobunaga",historicalCatalog:HistoricalStartCatalog.Current));}
    [Fact] public void CurrentMarkerIsSavedAndBoundToVersion(){var w=New();Assert.Equal(HistoricalStartCatalog.Current,w.NewGame!.HistoricalCatalog);Assert.Contains("HistoricalCatalog",System.Text.Encoding.UTF8.GetString(ContractJson.Write(w.NewGame)));var mutated=ContractJson.Copy(w);mutated.NewGame=mutated.NewGame! with{HistoricalCatalog=null};Assert.ThrowsAny<Exception>(()=>new WorldSession(mutated));}
    [Fact] public void EditionAndScenarioAreIndependentCopies(){var a=HistoricalStartCatalog.Edition;a.People[0]=a.People[0] with{Name="broken"};a.Sources[0]=a.Sources[0] with{Fact="broken"};var s=Scenario();s.People[0]=s.People[0] with{Name="broken"};Assert.DoesNotContain(HistoricalStartCatalog.Edition.People,p=>p.Name=="broken");Assert.DoesNotContain(Scenario().People,p=>p.Name=="broken");Assert.NotEqual("broken",HistoricalStartCatalog.Edition.Sources[0].Fact);}
    [Fact] public void UnknownSourceAndInvalidCandidateAreRejected(){var a=HistoricalStartCatalog.Edition;a.People[0]=a.People[0] with{SourceIds=["unknown"]};Assert.Throws<InvalidDataException>(()=>HistoricalStartCatalog.Validate(a));a=HistoricalStartCatalog.Edition;a.People[0]=a.People[0] with{HomeCandidate="unknown"};Assert.Throws<InvalidDataException>(()=>HistoricalStartCatalog.Validate(a));}
    [Fact] public void TrialPlacementDoesNotCreateRegionalOwnershipOrRemoteKnowledge(){var w=New();Assert.Single(w.LandRights,r=>r.Subject==new EntityId("org:otomo"));Assert.Single(w.LandRights,r=>r.Subject==new EntityId("org:shimazu"));Assert.Equal(2*w.Characters.Length,w.Grants.Length);var actor=new WorldSession(w).GetActorView(w.PlayerControl);Assert.DoesNotContain(actor.Messages,m=>m.KnownBody!=null);Assert.Empty(w.ServiceBonds);}
    [Theory][InlineData("person:yoshishige",0)][InlineData("person:yoshishige",1)][InlineData("person:yoshishige",6)][InlineData("person:takahisa",0)][InlineData("person:takahisa",1)][InlineData("person:takahisa",6)]
    public void WesternActorSaveRestoresAndContinuesExactWorld(string selected,int at){var initial=New(selected);var s=new WorldSession(initial);Assert.Equal(ResultCode.Accepted,s.Submit(NewGameWorld.Inspect(initial,"request:edition-inspect"),s.Revision).Code);if(at>0){s.SetPaused(false);s.AdvanceTo(at);}s.SetPaused(true);var store=new GenerationSaveStore(Path.Combine(Path.GetTempPath(),"start-edition-"+Guid.NewGuid().ToString("N")),initial.Definitions);store.Save(s,"test",initial.WorldId,new(0,1));var host=new WorldSessionHost(new(New(selected)));Assert.Equal(ResultCode.Accepted,host.CommitLoad(store.Prepare("test"),host.Current,host.Current.Revision));Assert.Equal(ContractJson.CanonicalHash(s.DiagnosticSnapshot()),ContractJson.CanonicalHash(host.Current.DiagnosticSnapshot()));foreach(var x in new[]{s,host.Current}){x.SetPaused(false);x.AdvanceTo(12);}Assert.Equal(ContractJson.CanonicalHash(s.DiagnosticSnapshot()),ContractJson.CanonicalHash(host.Current.DiagnosticSnapshot()));}
    [Fact] public void CampaignProfilePreservesEditionAndRejectsChangedMarker(){var store=new NewCampaignStore(Path.Combine(Path.GetTempPath(),"edition-profile-"+Guid.NewGuid().ToString("N")));var p=store.New(Scenario(),[],"person:yoshishige",20261022,NewGameWorld.CompactPersonalAuthority,HistoricalStartCatalog.Current);Assert.Equal(HistoricalStartCatalog.Current,store.Read(p.Instance).HistoricalCatalog);Assert.Equal(p.InitialHash,ContractJson.CanonicalHash(NewCampaignStore.Build(p)));Assert.Throws<InvalidDataException>(()=>NewCampaignStore.Build(p with{HistoricalCatalog=null}));}
}
